const body = $input.first().json.body || $input.first().json;
const personnummer = body.personnummer || '';
const message = body.message || '';
const chatHistory = body.chatHistory || [];
const sessionId = body.sessionId || 'session_' + Date.now();
const document = body.document || null;  // PASS THROUGH real document

// The frontend now determines the benefit type via the Classification AI 
// and passes it either in the body directly or appended to the first message.
let benefitType = body.benefitType || '';

if (!benefitType) {
  const btMatch = message.match(/BENEFIT_TYPE:(\w+)/);
  benefitType = btMatch ? btMatch[1] : 'carrier'; // Fallback safeguard
}

// Clean the hidden routing tag out of the message so the main AI doesn't see it
const cleanMessage = message.replace(/\s*BENEFIT_TYPE:\w+/, '').trim();

return [{ 
  json: { 
    personnummer, 
    message: cleanMessage, 
    chatHistory, 
    sessionId, 
    benefitType, 
    document 
  } 
}];

const result = $input.first().json;
const prevData = $('Parse Input').first().json;

let customerData = null;
let customerContext = 'Customer not found in the system.';

const customers = Array.isArray(result) ? result : [result];

if (customers.length > 0 && customers[0].personnummer) {
  customerData = customers[0];
  customerContext = 'Customer from system - Name: ' + customerData.full_name + ', ID: ' + customerData.personnummer + ', Email: ' + customerData.email + ', Phone: ' + customerData.phone + ', Employer: ' + customerData.employer + ', Type: ' + customerData.employment_type + ', Income: ' + customerData.monthly_income + ' SEK, Since: ' + customerData.employment_start;
}

return [{ json: { ...prevData, customerData, customerContext, customerFound: customerData !== null, customerName: customerData ? customerData.full_name : null } }];

const claudeResponse = $input.first().json;
const prevData = $('Build Claude Request').first().json;

const agentMessage = claudeResponse.content[0].text;
const updatedHistory = prevData.messages.concat([{ role: 'assistant', content: agentMessage }]);

const msg = agentMessage.toLowerCase();
const isComplete = msg.indexOf('your application is complete. i am now sending it to a caseworker for review') > -1;

// Extract a short summary line for the document bubble in the frontend
// Pull out key validated fields from the agent's response
let extractedSummary = '';
if (prevData.isDocUpload) {
  const lines = agentMessage.split('\n').filter(l => l.trim());
  // Find lines that contain validation info (names, dates, diagnoses)
  const summaryLines = lines.filter(l =>
    l.includes('✓') || l.includes('name') || l.includes('Name') ||
    l.includes('valid') || l.includes('confirmed') || l.includes('match')
  ).slice(0, 2);
  extractedSummary = summaryLines.join(' · ').replace(/[*#]/g, '').trim().substring(0, 120);
}

return [{ json: {
  reply: agentMessage,
  chatHistory: updatedHistory,
  sessionId: prevData.sessionId,
  customerData: prevData.customerData,
  customerFound: prevData.customerFound,
  customerName: prevData.customerName,
  isComplete: isComplete,
  personnummer: prevData.personnummer,
  benefitType: prevData.benefitType,
  extractedSummary: extractedSummary
} }];
